#!/bin/sh
# Regenerates docs/tool-contracts.md from the gateway's own tool schemas.
set -eu
cd "$(dirname "$0")/.."
cargo run -q -p sentinel-gateway -- schemas > target/tool-schemas.json
python3 - target/tool-schemas.json docs/tool-contracts.md <<'PY'
import json, sys
tools = json.load(open(sys.argv[1]))
out = ["# Tool contracts (v0.1)", "",
       "Generated by `scripts/gen-tool-contracts.sh` from `sentinel-ssh schemas`. Do not edit by hand.", "",
       "Every result is a `BoundedEnvelope`: `schema_version` \"1\", `outcome`, `data` (or `data_preview` plus `artifact_id` when truncated),",
       "`error` with a typed `code` and `retry` strategy on failure. Only malformed calls are JSON-RPC errors.", "",
       f"{len(tools)} tools:", ""]
out += [f"- [`{t['name']}`](#{t['name']})" for t in tools]
for t in tools:
    out += ["", f"## {t['name']}", "", t.get("description") or "", "",
            "<details><summary>Input schema</summary>", "", "```json", json.dumps(t["inputSchema"], indent=2), "```", "", "</details>", "",
            "<details><summary>Output schema</summary>", "", "```json", json.dumps(t["outputSchema"], indent=2), "```", "", "</details>"]
open(sys.argv[2], "w").write("\n".join(out) + "\n")
print(f"wrote {sys.argv[2]}: {len(tools)} tools")
PY
